-- Candidate/installed SQL must be enclosed in BEGIN and ROLLBACK
CREATE TEMP TABLE line_note_proof(name text PRIMARY KEY,status text NOT NULL DEFAULT 'PASS');
CREATE FUNCTION pg_temp.note_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
  IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Line notes check failed: %',label;END IF;INSERT INTO line_note_proof(name) VALUES(label);
END $$;
DO $$
DECLARE cafe uuid;actor uuid;warehouse uuid;party uuid:=gen_random_uuid();product uuid:=gen_random_uuid();item uuid:=gen_random_uuid();draft uuid:=gen_random_uuid();copy_draft uuid:=gen_random_uuid();bad_draft uuid:=gen_random_uuid();
  note1 uuid:=gen_random_uuid();note2 uuid:=gen_random_uuid();foreign_cafe uuid;foreign_owner uuid;foreign_draft uuid:=gen_random_uuid();staff_actor uuid;
  config jsonb;state jsonb;notes jsonb;payload jsonb;invoice jsonb;result jsonb;historical jsonb;copied jsonb;entry jsonb;tax_number text;denied boolean;draft_rows jsonb;current_source jsonb;
BEGIN
  SELECT c.id,c.owner_user_id INTO STRICT cafe,actor FROM public.cafes c WHERE slug='test-cafe';
  SELECT id INTO STRICT warehouse FROM public.bf_warehouses WHERE cafe_id=cafe AND active ORDER BY id LIMIT 1;
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  state:=public.brand_finance_invoice_line_notes(cafe);
  PERFORM pg_temp.note_assert(state='{"settings":{"enabled":false,"notes":[]},"revision":0}'::jsonb,'disabled empty default');
  config:=jsonb_build_object('enabled',true,'notes',jsonb_build_array(jsonb_build_object('id',note1,'text','العنوان الحصري - بدون سكر','active',true),jsonb_build_object('id',note2,'text','العنوان الحصري - ساخن','active',false)));
  state:=public.brand_finance_invoice_line_notes(cafe,'save',config,0);
  PERFORM pg_temp.note_assert(state->>'revision'='1' AND public.brand_finance_invoice_line_notes(cafe,'save',config,0)=state,'library save and lost response retry');
  PERFORM pg_temp.note_assert(public.brand_finance_invoice_line_notes(cafe,'options')->'notes'=jsonb_build_array(jsonb_build_object('id',note1,'text','العنوان الحصري - بدون سكر')),'options include active only');
  denied:=false;BEGIN PERFORM public.brand_finance_invoice_line_notes(cafe,'save',jsonb_set(config,'{enabled}','false'),0);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'library stale revision rejected');
  FOREACH entry IN ARRAY ARRAY['null'::jsonb,'[]'::jsonb,'{}'::jsonb,config||'{"unknown":true}'::jsonb,jsonb_set(config,'{notes}','[1]'),jsonb_set(config,'{notes,0,text}',to_jsonb(repeat('a',51))),jsonb_set(config,'{notes,0,text}','"   "'),jsonb_set(config,'{notes,1,text}',config#>'{notes,0,text}')] LOOP
    denied:=false;BEGIN PERFORM public.brand_finance_invoice_line_notes(cafe,'save',entry,1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
    IF NOT denied THEN RAISE EXCEPTION 'Malformed/long/empty/duplicate notes accepted';END IF;
  END LOOP;
  PERFORM pg_temp.note_assert(true,'library schema text length whitespace duplicates');
  config:=jsonb_set(config,'{enabled}','false');PERFORM public.brand_finance_invoice_line_notes(cafe,'save',config,1);
  result:=public.brand_finance_add_invoice_line_notes(cafe,jsonb_build_array('العنوان الحصري - مخصصة','العنوان الحصري - مخصصة','العنوان الحصري - بدون سكر'),2);
  PERFORM pg_temp.note_assert(result#>>'{settings,enabled}'='false' AND jsonb_array_length(result#>'{settings,notes}')=3 AND public.brand_finance_invoice_line_notes(cafe,'options')->'notes'='[]'::jsonb,'custom library add deduplicates and keeps disabled');
  PERFORM pg_temp.note_assert(public.brand_finance_add_invoice_line_notes(cafe,jsonb_build_array('العنوان الحصري - مخصصة'),2)=result,'custom library lost response retry');
  config:=result->'settings';config:=jsonb_set(config,'{notes}',jsonb_build_array(config#>'{notes,2}',config#>'{notes,0}',config#>'{notes,1}'));config:=jsonb_set(config,'{enabled}','true');
  PERFORM public.brand_finance_invoice_line_notes(cafe,'save',config,3);
  PERFORM pg_temp.note_assert(public.brand_finance_invoice_line_notes(cafe,'options')#>>'{notes,0,text}'='العنوان الحصري - مخصصة','library sorted order preserved');
  INSERT INTO public.bf_parties(id,cafe_id,name,kind) VALUES(party,cafe,'العنوان الحصري - عميل اختبار ملاحظات','customer');
  INSERT INTO public.menu_products(id,cafe_id,name,price) VALUES(product,cafe,'العنوان الحصري - صنف اختبار ملاحظات',20);
  INSERT INTO public.bf_items(id,cafe_id,name,sku) VALUES(item,cafe,'العنوان الحصري - مخزون اختبار ملاحظات','NOTES-'||item::text);
  INSERT INTO public.bf_item_product_links(cafe_id,item_id,product_id,quantity) VALUES(cafe,item,product,2);
  INSERT INTO public.bf_stock(cafe_id,warehouse_id,item_id,quantity,average_cost,value,cost_known) VALUES(cafe,warehouse,item,100,3,300,true);
  SELECT coalesce(nullif(trim(s.tax_number),''),'300000000000003') INTO tax_number FROM public.cafe_settings s WHERE s.cafe_id=cafe;
  payload:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',41,'productId',product,'quantity',2,'price',20,'vatRate',15,'description','وصف مستقل'),jsonb_build_object('key',7,'productId',product,'quantity',1,'price',20,'vatRate',15)),'warehouseId',warehouse,'partyId',party,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','vatRate',15,'taxInclusive',false,'note','العنوان الحصري - اختبار الملاحظات'),
    'issuer',jsonb_build_object('name','العنوان الحصري','vatNumber',coalesce(tax_number,'300000000000003'),'address','العنوان الحصري الرياض عنوان الاختبار'),'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb,'supplyDate',(now() AT TIME ZONE 'Asia/Riyadh')::date);
  current_source:=public.brand_finance_order_sources(cafe);IF current_source#>>'{settings,required}'='true' THEN PERFORM public.brand_finance_order_sources(cafe,'save',jsonb_set(current_source->'settings','{required}','false'),(current_source->>'revision')::integer);END IF;
  PERFORM public.brand_finance_save_invoice_draft(cafe,draft,0,payload);
  notes:=jsonb_build_array(jsonb_build_object('key',41,'notes',jsonb_build_array('العنوان الحصري - بدون سكر')),jsonb_build_object('key',7,'notes',jsonb_build_array('العنوان الحصري - ملاحظة مخصصة')));
  result:=public.brand_finance_set_invoice_line_notes(cafe,draft,1,0,notes);
  PERFORM pg_temp.note_assert(result->>'revision'='1' AND result#>>'{lines,0,key}'='7','selection keyed and canonically ordered');
  PERFORM pg_temp.note_assert(public.brand_finance_set_invoice_line_notes(cafe,draft,1,0,notes)=result,'selection lost response retry');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_line_notes(cafe,draft,1,0,'[]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'selection conflict rejects overwrite');
  FOREACH entry IN ARRAY ARRAY[jsonb_set(notes,'{0,key}','99'),notes||jsonb_build_array(notes->0),jsonb_set(notes,'{0,notes}',jsonb_build_array(repeat('a',51))),jsonb_set(notes,'{0,notes}','[]'),jsonb_set(notes,'{0,notes}','["same","same"]'),jsonb_set(notes,'{0,key}','0.1')] LOOP
    denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_line_notes(cafe,draft,1,1,entry);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
    IF NOT denied THEN RAISE EXCEPTION 'Invalid selection accepted';END IF;
  END LOOP;
  PERFORM pg_temp.note_assert(true,'selection unknown duplicate fractional keys text limits empty and duplicates');
  payload:=jsonb_set(payload,'{invoice,lines}',jsonb_build_array(payload#>'{invoice,lines,1}',payload#>'{invoice,lines,0}'));
  PERFORM public.brand_finance_save_invoice_draft(cafe,draft,1,payload);
  denied:=false;BEGIN PERFORM public.brand_finance_issue_company_invoice(cafe,draft,2,69);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied AND NOT EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE draft_id=draft) AND (SELECT quantity FROM public.bf_stock WHERE cafe_id=cafe AND item_id=item AND warehouse_id=warehouse)=100,'stale note binding rolls back whole financial issuance');
  result:=public.brand_finance_set_invoice_line_notes(cafe,draft,2,0,notes);
  PERFORM pg_temp.note_assert(result->>'revision'='1' AND (SELECT draft_revision FROM public.bf_invoice_line_note_drafts WHERE draft_id=draft)=2,'same notes refresh draft binding after reorder');
  invoice:=public.brand_finance_issue_company_invoice(cafe,draft,2,69);
  historical:=public.brand_finance_issued_line_notes(cafe,(invoice->>'id')::uuid);
  PERFORM pg_temp.note_assert(historical->>'recorded'='true' AND historical#>>'{lines,0,lineIndex}'='0' AND historical#>>'{lines,0,key}'='7' AND historical#>>'{lines,0,notes,0}'='العنوان الحصري - ملاحظة مخصصة' AND historical#>>'{lines,1,key}'='41' AND invoice#>>'{lines,1,description}'='وصف مستقل','historical notes align reordered snapshot and remain separate from description');
  PERFORM pg_temp.note_assert((invoice->>'total')::numeric=69 AND (SELECT sum(debit-credit) FROM public.bf_journal WHERE document_id=(invoice->>'id')::uuid)=0 AND (SELECT quantity FROM public.bf_stock WHERE cafe_id=cafe AND item_id=item AND warehouse_id=warehouse)=94,'canonical amount balanced journal and stock unchanged');
  PERFORM pg_temp.note_assert(public.brand_finance_invoice_order_source(cafe,(invoice->>'id')::uuid)->>'recorded'='true','order source snapshot preserved');
  PERFORM pg_temp.note_assert(public.brand_finance_issue_company_invoice(cafe,draft,-1,-1)=invoice AND public.brand_finance_set_invoice_line_notes(cafe,draft,1,0,notes)->>'issued'='true','issued invoice and note retry idempotent');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_line_notes(cafe,draft,2,1,'[]');EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'issued notes immutable');
  config:=jsonb_build_object('enabled',false,'notes','[]'::jsonb);PERFORM public.brand_finance_invoice_line_notes(cafe,'save',config,4);
  PERFORM pg_temp.note_assert(public.brand_finance_issued_line_notes(cafe,(invoice->>'id')::uuid)=historical,'library deletion and disable preserve historical notes');
  SELECT jsonb_agg(jsonb_build_object('key',r.position-1,'productId',r.value->'productId','name',r.value->'name','kind',r.value->'kind','quantity',r.value->'quantity','price',r.value->'price','vatRate',r.value->'vatRate','description',r.value->'description') ORDER BY r.position) INTO draft_rows FROM jsonb_array_elements(invoice->'lines') WITH ORDINALITY r(value,position);
  payload:=jsonb_set(payload,'{invoice,lines}',draft_rows);PERFORM public.brand_finance_save_invoice_draft(cafe,copy_draft,0,payload);
  copied:=public.brand_finance_copy_invoice_line_notes(cafe,(invoice->>'id')::uuid,copy_draft,1);
  PERFORM pg_temp.note_assert(copied#>>'{lines,0,key}'='0' AND copied#>>'{lines,0,notes,0}'='العنوان الحصري - ملاحظة مخصصة' AND copied#>>'{lines,1,key}'='1','copy uses snapshot indices with library disabled');
  PERFORM pg_temp.note_assert(public.brand_finance_copy_invoice_line_notes(cafe,(invoice->>'id')::uuid,copy_draft,1)=copied,'copy lost response retry');
  result:=public.brand_finance_invoice_line_note_context(cafe,copy_draft);
  PERFORM pg_temp.note_assert(result->>'enabled'='false' AND result->'notes'='[]'::jsonb AND result->'lines'=copied->'lines','disabled library context retains draft notes');
  PERFORM public.brand_finance_save_invoice_draft(cafe,bad_draft,0,jsonb_set(payload,'{invoice,lines,0,quantity}','3'));
  denied:=false;BEGIN PERFORM public.brand_finance_copy_invoice_line_notes(cafe,(invoice->>'id')::uuid,bad_draft,1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied AND NOT EXISTS(SELECT 1 FROM public.bf_invoice_line_note_drafts WHERE draft_id=bad_draft),'copy rejects mismatched line identity');
  result:=brand_finance_private.issue_company_invoice(cafe,copy_draft,1,69,NULL,'');
  PERFORM pg_temp.note_assert(public.brand_finance_issued_line_notes(cafe,(result->>'id')::uuid)='{"recorded":false,"lines":[]}'::jsonb,'internal recurring issuer remains unchanged');
  SELECT c.id,c.owner_user_id INTO STRICT foreign_cafe,foreign_owner FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id WHERE c.id<>cafe AND c.owner_user_id<>actor AND p.status='active' AND c.deleted_at IS NULL AND c.status IN('active','published') AND platform_access_private.service_enabled(c.id,'finance') AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=c.id AND s.user_id=actor AND s.active) LIMIT 1;
  INSERT INTO public.bf_invoice_drafts(id,cafe_id,payload,revision,created_by,updated_by) VALUES(foreign_draft,foreign_cafe,payload,1,foreign_owner,foreign_owner);
  denied:=false;BEGIN PERFORM public.brand_finance_invoice_line_note_context(cafe,foreign_draft);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'cross tenant draft read denied');
  denied:=false;BEGIN PERFORM public.brand_finance_set_invoice_line_notes(cafe,foreign_draft,1,0,'[]');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'cross tenant draft notes write denied');
  denied:=false;BEGIN PERFORM public.brand_finance_issued_line_notes(foreign_cafe,(invoice->>'id')::uuid);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'cross tenant issued notes denied');
  SELECT p.id INTO STRICT staff_actor FROM public.profiles p WHERE p.id<>actor AND p.role<>'platform_admin' AND p.status='active' AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=cafe AND s.user_id=p.id) LIMIT 1;
  INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(cafe,staff_actor,'العنوان الحصري - محاسب اختبار ملاحظات','accountant');
  PERFORM set_config('request.jwt.claim.sub',staff_actor::text,true);
  PERFORM pg_temp.note_assert(public.brand_finance_invoice_line_notes(cafe)->>'revision'='5','accountant can read library');
  denied:=false;BEGIN PERFORM public.brand_finance_add_invoice_line_notes(cafe,'["sample"]',5);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'accountant cannot append library');
  UPDATE public.bf_staff SET role='cashier' WHERE cafe_id=cafe AND user_id=staff_actor;
  denied:=false;BEGIN PERFORM public.brand_finance_invoice_line_note_context(cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'cashier denied administrative notes');
  PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{}',true);
  denied:=false;BEGIN PERFORM public.brand_finance_invoice_line_notes(cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.note_assert(denied,'anonymous denied');
  PERFORM pg_temp.note_assert(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'brand_finance_%line_note%' AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE') OR NOT has_function_privilege('authenticated',p.oid,'EXECUTE'))),'all note RPC least privilege');
  PERFORM pg_temp.note_assert(NOT EXISTS(SELECT 1 FROM pg_class WHERE oid IN('public.bf_invoice_line_note_settings'::regclass,'public.bf_invoice_line_note_events'::regclass,'public.bf_invoice_line_note_drafts'::regclass,'public.bf_invoice_line_notes'::regclass) AND (NOT relrowsecurity OR has_table_privilege('authenticated',oid,'SELECT') OR has_table_privilege('anon',oid,'INSERT'))),'all note tables RLS and private');
  SET CONSTRAINTS ALL IMMEDIATE;
END $$;
SELECT count(*) checks,jsonb_agg(to_jsonb(p) ORDER BY name) results FROM line_note_proof p;
